from lib import *
chapter(6,'science','the-wonderful-world-of-science','The Wonderful World of Science',
 ('Why does the ball bounce?','Asha drops a ball and it bounces. She asks, why does it bounce? Asking such questions is how science begins. In this chapter we learn how scientists think and work.'),
 [('What is science?',['Science is a way of finding out how the world works by asking questions, observing, testing and thinking.','Science is not only in laboratories. It is in the kitchen, the garden, the playground and the sky.','People across India and the world have studied nature for thousands of years, and each generation adds new knowledge.']),
  ('Curiosity and questions',['Curiosity means wanting to know. A curious mind asks what, how and why.','A good question can be tested. Why does this plant grow towards the window is a good question to investigate.']),
  ('The scientific method',['Scientists follow steps: observe, ask a question, make a guess called a hypothesis, test it by an experiment, record results and draw a conclusion.','An experiment must be fair. We change only one thing at a time and keep the rest the same.','Results should be recorded honestly even if they surprise us. Repeating an experiment helps to be sure.']),
  ('Science and our lives',['Science helps us make medicines, grow more food, build bridges and send rockets to space.','Science also asks us to be careful: always follow safety rules and respect living things and the environment.'])],
 [('Plan a fair test: does a plant need light to grow?',[('Take two identical plants with the same soil and water.','Keep everything the same.'),('Put one in light and one in a dark cupboard.','Change only the light.'),('Observe after a week and compare.','Record what you see.')])],
 ('A friend says a plant grows taller with music. How would you check this fairly?',['Two plants identical in every way except music.','Measure heights at the same time each day.'],['Changing many things at once.','Believing without testing.']),
 ['Science begins with curiosity.','Steps: observe, ask, hypothesise, test, record, conclude.','A fair test changes only one thing.','Science helps us live better and needs safety and care.'],
 [mcq('w1-1',1,'What is a hypothesis?','A guess that can be tested',[('A final answer','It may turn out to be wrong after testing.'),('A measuring tool','A hypothesis is an idea, not a tool.')],'We test the guess by experiment.'),
  mcq('w1-2',1,'In a fair test we change','only one thing',[('everything','Then we cannot tell what caused the result.'),('nothing','Without a change there is nothing to compare.')],'Keep the other conditions the same.'),
  tf('w1-3',1,'Science is done only in laboratories.',False,'Science happens wherever we observe and ask questions.'),
  mcq('w1-4',1,'The first step of investigating is usually to','observe and ask a question',[('write the conclusion','The conclusion comes last.'),('buy equipment','Questions come first.')],'Observation raises questions.'),
  mcq('w1-5',2,'Why should an experiment be repeated?','To be sure the result is reliable',[('To waste time','Repetition checks reliability.'),('To change the hypothesis','The hypothesis changes only if results require it.')],'One result may be a chance event.'),
  tf('w1-6',2,'We should record only the results we like.',False,'Honest recording of all results is essential.'),
  mcq('w1-7',2,'Which is a testable question?','Does salt dissolve faster in warm water?',[('Is blue the best colour?','That is a matter of opinion.'),('Who is the nicest teacher?','Not measurable.')],'We can measure how fast it dissolves.'),
  mcq('w1-8',2,'A safety rule in the lab is to','follow the teacher\'s instructions',[('taste chemicals','Never taste unknown substances.'),('run around','Running causes accidents.')],'Safety first.'),
  mcq('w1-9',3,'Two plants, one in light and one in dark. The thing changed is','light',[('water','Water is kept the same.'),('soil','Soil is kept the same.')],'Only light differs.'),
  mcq('w1-10',3,'A conclusion is','what the results tell us',[('what we hoped for','Conclusions follow the results, not wishes.'),('the question itself','The question comes first.')],'It is drawn from evidence.')],
 keep=['hypothesis','experiment','observation'])
chapter(6,'science','diversity-in-the-living-world','Diversity in the Living World',
 ('The school garden','In a small school garden we find grass, a neem tree, ants, a butterfly and a frog. Each is different. Why are there so many kinds of living things, and how can we group them?'),
 [('Diversity',['Diversity means variety. Earth has a huge variety of plants and animals in forests, deserts, oceans and cities.','Living things differ in size, shape, colour and where they live.']),
  ('Grouping plants',['We can group plants by what they look like. Herbs are small plants with soft green stems. Shrubs are bushy with many woody branches. Trees are tall with one thick woody trunk.','Climbers need support to climb up. Creepers spread along the ground.','Plants can also be grouped by leaves, flowers, roots and stems.']),
  ('Grouping animals',['Animals can be grouped by what they eat: herbivores eat plants, carnivores eat animals, omnivores eat both.','Animals can be grouped by where they live: on land, in water or both, like frogs, which are amphibians.','Some animals have a backbone (vertebrates, such as fish, birds and mammals) and some do not (invertebrates, such as insects and worms).']),
  ('Adaptations',['A feature that helps a living thing survive in its surroundings is an adaptation.','A camel stores fat in its hump and can go many days without water. A fish has gills and fins for living in water.','Plants in deserts, like cactus, have thick stems that store water and thin spines instead of leaves.']),
  ('Why grouping helps',['Grouping helps us study and remember so many living things.','It also shows how living things are related to one another.'])],
 [('Group these: tiger, cow, crow, frog.',[('Tiger eats flesh, so it is a carnivore.','Look at food.'),('Cow eats plants, so it is a herbivore; crow and frog are different groups by body and habitat.','Use a rule to group.')])],
 ('Explain why a cactus can live in a desert.',['It stores water in its stem.','It has spines that lose very little water.'],['Thinking all plants need lots of water.','Confusing herbivore and carnivore.']),
 ['Diversity means variety of living things.','Plants group as herbs, shrubs, trees, climbers and creepers.','Animals group by food, habitat and backbone.','Adaptations help living things survive.'],
 [mcq('l2-1',1,'A tall plant with a thick woody trunk is a','tree',[('herb','Herbs are small with soft stems.'),('creeper','Creepers spread on the ground.')],'Trees have a woody trunk.'),
  mcq('l2-2',1,'An animal that eats only plants is a','herbivore',[('carnivore','Carnivores eat other animals.'),('omnivore','Omnivores eat both.')],'Herbi means plant.'),
  mcq('l2-3',1,'A frog lives on','land and in water',[('only land','Frogs need water to breed.'),('only water','Adult frogs also live on land.')],'It is an amphibian.'),
  tf('l2-4',1,'Fish have gills for breathing in water.',True,'Gills take oxygen from water.'),
  mcq('l2-5',2,'A feature that helps survival is called','an adaptation',[('a habit','A habit is something repeated.'),('a disease','Diseases harm living things.')],'Adaptations suit the surroundings.'),
  mcq('l2-6',2,'Animals with a backbone are','vertebrates',[('invertebrates','They lack a backbone.'),('herbivores','This is about food, not backbone.')],'Fish, birds, reptiles and mammals.'),
  mcq('l2-7',2,'Which is an invertebrate?','Earthworm',[('Frog','Frogs have a backbone.'),('Sparrow','Birds have a backbone.')],'Worms have no backbone.'),
  mcq('l2-8',2,'A plant that needs a support to climb is a','climber',[('shrub','Shrubs stand on their own.'),('herb','Herbs are small.')],'It twines around the support.'),
  mcq('l2-9',3,'Why do we group living things?','To study and remember them easily',[('To keep them apart','Grouping is for understanding.'),('To rename them','Grouping does not rename.')],'Groups show similarities.'),
  tf('l2-10',3,'A camel\'s hump stores fat.',True,'It is a store of energy, not water.')],
 keep=['diversity','adaptation','herbivore'])
chapter(6,'science','mindful-eating-a-path-to-a-healthy-body','Mindful Eating: A Path to a Healthy Body',
 ('Lunch box','Ravi opens his lunch box and finds roti, dal, vegetables and a banana. Which part gives him energy, which helps him grow and which keeps him healthy? Let us look at food closely.'),
 [('What do we eat?',['Different regions of India have different foods, but all of them come from plants or animals.','Food gives us energy, helps us grow and repair our bodies and keeps us healthy.']),
  ('Components of food',['The main components are carbohydrates, proteins, fats, vitamins, minerals, fibre and water.','Carbohydrates, such as in rice and roti, give energy. Proteins, in dal, eggs and milk, help growth and repair.','Fats, in ghee and oil, give a lot of energy. Vitamins and minerals protect us from diseases.','Fibre helps digestion and water keeps the body working.']),
  ('Testing for components',['Iodine solution turns blue-black when starch is present.','A paper rubbed with a food that contains fat shows an oily patch that stays when dry.','Testing helps us find what a food contains.']),
  ('Balanced diet',['A balanced diet has all the components in the right amount.','Not eating enough of something causes deficiency diseases. For example lack of vitamin C can cause bleeding gums, and lack of iron causes weakness.','Eating too much junk food can lead to being overweight.']),
  ('Millets and food miles',['Millets such as ragi and jowar are cereals rich in nutrients that grow with little water.','Food miles are the distance food travels from farm to plate. Local food has fewer food miles and is often fresher.']),
  ('Mindful eating',['Eat slowly, chew well, avoid wasting food and wash your hands before eating.','Choose fresh and home cooked meals and drink enough water.'])],
 [('Which food group does dal belong to?',[('Dal is rich in protein.','It helps growth and repair.'),('So it is a protein food.','Classify by main nutrient.')])],
 ('Explain why a balanced diet is better than eating only one kind of food.',['The body needs many components.','One food cannot give them all.'],['Thinking only energy foods are needed.','Skipping vegetables.']),
 ['Food gives energy, growth and protection.','Carbohydrates, proteins, fats, vitamins, minerals, fibre, water.','Iodine tests for starch.','A balanced diet is needed.','Millets and local foods are good choices.'],
 [mcq('e3-1',1,'Which gives us quick energy?','Carbohydrates',[('Water','Water does not provide energy.'),('Fibre','Fibre helps digestion.')],'Rice and roti are rich in them.'),
  mcq('e3-2',1,'Iodine turns blue-black in the presence of','starch',[('fat','Fat leaves a grease spot.'),('protein','Proteins need another test.')],'It is the test for starch.'),
  tf('e3-3',1,'Proteins help the body grow and repair.',True,'Dal, eggs and milk are protein foods.'),
  mcq('e3-4',1,'A balanced diet contains','all components in right amounts',[('only fats','The body needs all components.'),('only sweets','Sweets lack many nutrients.')],'Variety is the key.'),
  mcq('e3-5',2,'Lack of vitamin C can cause','bleeding gums',[('strong bones','Bones need calcium.'),('weight gain','Deficiency causes illness.')],'Citrus fruits give vitamin C.'),
  mcq('e3-6',2,'Which is a millet?','Ragi',[('Rice','Rice is not a millet.'),('Wheat','Wheat is a different cereal.')],'Ragi and jowar are millets.'),
  mcq('e3-7',2,'Food miles measure','distance food travels from farm to plate',[('the cost of food','Money is not distance.'),('food quality','Quality is separate.')],'Fewer miles means fresher food.'),
  tf('e3-8',2,'Fibre helps digestion.',True,'It keeps the food moving.'),
  mcq('e3-9',3,'An oily patch on paper shows that a food has','fat',[('starch','Starch needs iodine.'),('minerals','Minerals leave no patch.')],'The grease stays after drying.'),
  mcq('e3-10',3,'Mindful eating includes','eating slowly and not wasting food',[('eating while running','That is not mindful.'),('skipping meals','Skipping harms health.')],'Pay attention to what and how you eat.')],
 keep=['carbohydrate','protein','vitamin','balanced diet'])
